API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(PerimeterRouter, "Perimeter Router", "Azure API Gateway", "Perimeter routing and WAF for incoming traffic.")
    Component(SchemaValidator, "Schema Validator", "Azure API Gateway", "Validates schema for incoming requests.")
    Component(RateLimiter, "Rate Limiter", "Azure API Gateway", "Enforces rate-limiting and circuit-breaking.")
}

Rel(PerimeterRouter, SchemaValidator, "Routes requests for validation")
Rel(SchemaValidator, RateLimiter, "Passes validated requests for rate-limiting")

@enduml

Azure Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Azure Redis container

System_Ext(ClaimsWeb, "Claims Web App", "Container from external context")

Container_Boundary(AzureRedis, "Azure Redis") {
    Component(UI Acceleration Cache, "UI Acceleration Cache", "Azure Cache for Redis", "Caches reference data and supports UI acceleration to maintain sub-2-second response times.")
    Component(Session Management Store, "Session Management Store", "Azure Cache for Redis", "Manages secure user sessions for claims adjusters interacting with the Claims Web App.")
}

Rel(ClaimsWeb, UI Acceleration Cache, "Reads reference data and UI caches", "TLS 1.2 / TCP")
Rel(ClaimsWeb, Session Management Store, "Manages user sessions", "TLS 1.2 / TCP")

@enduml

Azure Service Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Azure_Service_Bus", "Azure Service Bus") {
    Component(Claim_Submission_Topic, "Claim Submission Topic", "Azure Service Bus Topic", "Receives asynchronous claim submission messages from the Claims Web App and distributes them to subscriptions.")
    Component(Claim_Processing_Subscription, "Claim Processing Subscription", "Azure Service Bus Subscription", "Queues claim messages for consumption by backend integration and processing services.")
    Component(Dead_Letter_Queue_DLQ, "Dead-Letter Queue (DLQ)", "Azure Service Bus DLQ", "Captures malformed or failed claim messages for error governance and manual auditing.")
}

Rel(Claim_Submission_Topic, Claim_Processing_Subscription, "Routes messages to", "")
Rel(Claim_Processing_Subscription, Dead_Letter_Queue_DLQ, "Forwards failed messages to", "")
@enduml
